-- Add seven more dating words to the love category (operator instruction 2026-09-06).
-- 남사친/여사친/밀당/모솔/어장관리/환승이별/그린라이트 — all have transparent,
-- well-documented etymologies (clippings and metaphors), so no invented origins.
-- 모솔 is the headword (dominant spoken form) with 모태솔로 as its alias.
--
-- NOTE: filename timestamp differs from the production migration version
-- (MCP apply time becomes the version) — repo-wide convention, see CLAUDE.md.

begin;

insert into public.words (id, word, romanization, category, short_desc, short_desc_i18n, pronunciation, meanings, origin, origin_i18n, usage, usage_i18n, related_words, likes, saves, translations, aliases) values
('288', '남사친', 'Nam-Sa-Chin', 'love', '''남자 사람 친구'' — 연애 감정 없는 남자인 친구',
 '{"en":"A guy friend with zero romance (man-human-friend)","ja":"恋愛感情なしの男友達(男・人間・友達の略)","es":"Amigo hombre sin romance","vi":"Bạn nam đơn thuần, không yêu đương","de":"Rein platonischer männlicher Freund"}'::jsonb,
 '[남사친]',
 '[{"type":"명사","definition":"''남자 사람 친구''의 줄임말. ''남친''(애인)과 구분하려고 가운데 ''사람''을 끼워 넣어, 연애 감정 없이 그냥 친한 남자임을 강조한다.","definition_i18n":{"en":"Short for 남자 사람 친구 (man-human-friend). The extra 사람 (human) separates him from a 남친 (boyfriend) — just a friend who happens to be a guy.","ja":"「男・人間・友達」の略。「남친」(彼氏)と区別するために「人間」を挟み、恋愛感情なしのただの男友達だと強調する。","es":"Abreviatura de 남자 사람 친구 (hombre-persona-amigo). El 사람 (persona) extra lo distingue del 남친 (novio): solo un amigo que es chico.","vi":"Viết tắt của 남자 사람 친구 (nam-người-bạn). Chữ 사람 chen vào để phân biệt với 남친 (người yêu) — chỉ là bạn nam bình thường.","de":"Kurz für 남자 사람 친구 (Mann-Mensch-Freund). Das eingeschobene 사람 trennt ihn vom 남친 (fester Freund) — einfach ein Kumpel."},"examples":[{"kor":"걔는 그냥 남사친이야, 오해하지 마.","eng":"He is just a guy friend — do not get the wrong idea.","ja":"彼はただの男友達だよ、誤解しないで。","es":"Es solo un amigo, no te confundas.","vi":"Cậu ấy chỉ là bạn nam thôi, đừng hiểu lầm.","de":"Er ist nur ein Kumpel — versteh das nicht falsch."}]}]'::jsonb,
 '''남친''(애인)과 헷갈리지 않도록 ''사람''을 끼워 만든 조어. 2010년대 연애 예능·커뮤니티에서 정착했다.',
 '{"en":"Coined by inserting 사람 (human) so it cannot be confused with 남친 (boyfriend); settled in the 2010s via dating shows and online communities.","ja":"「남친」(彼氏)と混同しないよう「사람」を挟んだ造語。2010年代に恋愛番組やコミュニティで定着。","es":"Acuñado insertando 사람 (persona) para no confundirlo con 남친 (novio); se asentó en los 2010 con los programas de citas.","vi":"Tạo ra bằng cách chen 사람 (người) để khỏi nhầm với 남친 (bạn trai); phổ biến từ thập niên 2010 qua show hẹn hò.","de":"Gebildet mit eingeschobenem 사람 (Mensch), um Verwechslung mit 남친 zu vermeiden; etabliert in den 2010ern durch Dating-Shows."}'::jsonb,
 '연인 관계가 아님을 분명히 할 때 쓴다. ''여사친''과 짝을 이룬다.',
 '{"en":"Used to make clear there is no romance; pairs with 여사친.","ja":"恋人関係ではないと明確にするときに使う。「여사친」と対になる。","es":"Se usa para dejar claro que no hay romance; hace pareja con 여사친.","vi":"Dùng để khẳng định không có yêu đương; đi cặp với 여사친.","de":"Stellt klar, dass keine Romanze besteht; Gegenstück zu 여사친."}'::jsonb,
 array['여사친','남친'], 0, 0,
 '[{"lang":"🇺🇸 EN","text":"Guy friend (platonic)"},{"lang":"🇯🇵 JA","text":"ただの男友達"},{"lang":"🇨🇳 ZH","text":"纯男性朋友"},{"lang":"🇻🇳 VI","text":"Bạn nam đơn thuần"},{"lang":"🇪🇸 ES","text":"Amigo (sin romance)"},{"lang":"🇩🇪 DE","text":"Platonischer Kumpel"}]'::jsonb, null),
('289', '여사친', 'Yeo-Sa-Chin', 'love', '''여자 사람 친구'' — 연애 감정 없는 여자인 친구',
 '{"en":"A girl friend with zero romance (woman-human-friend)","ja":"恋愛感情なしの女友達(女・人間・友達の略)","es":"Amiga mujer sin romance","vi":"Bạn nữ đơn thuần, không yêu đương","de":"Rein platonische Freundin"}'::jsonb,
 '[여사친]',
 '[{"type":"명사","definition":"''여자 사람 친구''의 줄임말. ''여친''(애인)과 구분하려고 ''사람''을 끼워, 연애 감정 없는 여자인 친구임을 강조한다.","definition_i18n":{"en":"Short for 여자 사람 친구 (woman-human-friend). The extra 사람 separates her from a 여친 (girlfriend) — just a friend who happens to be a girl.","ja":"「女・人間・友達」の略。「여친」(彼女)と区別するために「人間」を挟み、恋愛感情なしの女友達だと強調する。","es":"Abreviatura de 여자 사람 친구 (mujer-persona-amiga). El 사람 extra la distingue de la 여친 (novia): solo una amiga.","vi":"Viết tắt của 여자 사람 친구 (nữ-người-bạn). Chữ 사람 chen vào để phân biệt với 여친 (người yêu) — chỉ là bạn nữ bình thường.","de":"Kurz für 여자 사람 친구 (Frau-Mensch-Freundin). Das 사람 trennt sie von der 여친 (feste Freundin) — einfach eine Freundin."},"examples":[{"kor":"여사친이랑 밥 먹는 것도 눈치 보여?","eng":"Do I really need permission to grab a meal with a girl friend?","ja":"女友達とご飯食べるのも気を使うの?","es":"¿Ni siquiera puedo comer con una amiga sin dar explicaciones?","vi":"Ăn cơm với bạn nữ thôi cũng phải nhìn trước ngó sau à?","de":"Muss ich mich schon rechtfertigen, wenn ich mit einer Freundin essen gehe?"}]}]'::jsonb,
 '''여친''(애인)과 헷갈리지 않도록 ''사람''을 끼워 만든 조어. ''남사친''과 같은 시기에 정착했다.',
 '{"en":"Coined by inserting 사람 so it cannot be confused with 여친 (girlfriend); settled alongside 남사친.","ja":"「여친」(彼女)と混同しないよう「사람」を挟んだ造語。「남사친」と同時期に定着。","es":"Acuñado insertando 사람 para no confundirla con 여친 (novia); se asentó junto a 남사친.","vi":"Tạo ra bằng cách chen 사람 để khỏi nhầm với 여친 (bạn gái); phổ biến cùng thời với 남사친.","de":"Gebildet mit 사람, um Verwechslung mit 여친 zu vermeiden; etabliert zeitgleich mit 남사친."}'::jsonb,
 '연인 관계가 아님을 분명히 할 때 쓴다. ''남사친''과 짝을 이룬다.',
 '{"en":"Used to make clear there is no romance; pairs with 남사친.","ja":"恋人関係ではないと明確にするときに使う。「남사친」と対になる。","es":"Se usa para dejar claro que no hay romance; hace pareja con 남사친.","vi":"Dùng để khẳng định không có yêu đương; đi cặp với 남사친.","de":"Stellt klar, dass keine Romanze besteht; Gegenstück zu 남사친."}'::jsonb,
 array['남사친','여친'], 0, 0,
 '[{"lang":"🇺🇸 EN","text":"Girl friend (platonic)"},{"lang":"🇯🇵 JA","text":"ただの女友達"},{"lang":"🇨🇳 ZH","text":"纯女性朋友"},{"lang":"🇻🇳 VI","text":"Bạn nữ đơn thuần"},{"lang":"🇪🇸 ES","text":"Amiga (sin romance)"},{"lang":"🇩🇪 DE","text":"Platonische Freundin"}]'::jsonb, null),
('290', '밀당', 'Mil-Dang', 'love', '''밀고 당기기'' — 연애 주도권 심리전',
 '{"en":"Push-and-pull — the dating power game","ja":"駆け引き(押して引く)","es":"Tira y afloja romántico","vi":"Chiến thuật kéo-đẩy khi yêu","de":"Das Hin und Her beim Daten"}'::jsonb,
 '[밀당]',
 '[{"type":"명사","definition":"''밀고 당기기''의 줄임말. 마음을 다 보여주지 않고 관심을 줬다 뺐다 하며 연애 주도권을 잡으려는 심리전.","definition_i18n":{"en":"Short for push-and-pull: giving and withdrawing attention to keep the upper hand in a budding romance.","ja":"「押して引く」の略。気持ちを全部見せず、関心を与えたり引っ込めたりして恋愛の主導権を握ろうとする駆け引き。","es":"Abreviatura de empujar-y-tirar: dar y retirar atención para llevar la ventaja en el cortejo.","vi":"Viết tắt của đẩy-và-kéo: lúc quan tâm lúc thờ ơ để nắm thế chủ động trong tình cảm.","de":"Kurz für Schieben-und-Ziehen: Aufmerksamkeit geben und entziehen, um beim Anbandeln die Oberhand zu behalten."},"examples":[{"kor":"밀당 그만하고 그냥 좋아한다고 말해.","eng":"Stop playing push-and-pull and just say you like her.","ja":"駆け引きはやめて、好きって言いなよ。","es":"Deja el tira y afloja y dile que te gusta.","vi":"Đừng kéo-đẩy nữa, cứ nói thích người ta đi.","de":"Hör auf mit dem Hin und Her und sag einfach, dass du sie magst."}]}]'::jsonb,
 '''밀다''와 ''당기다''를 합쳐 줄인 말. 2000년대 연애 상담·예능 프로그램을 통해 퍼졌다.',
 '{"en":"A clipping of 밀다 (push) + 당기다 (pull); spread through 2000s dating-advice shows.","ja":"「押す」と「引く」を合わせて縮めた語。2000年代の恋愛相談・バラエティで広まった。","es":"Recorte de 밀다 (empujar) + 당기다 (tirar); se difundió con los programas de consejos amorosos de los 2000.","vi":"Ghép rút gọn của 밀다 (đẩy) + 당기다 (kéo); lan rộng qua các show tư vấn tình cảm thập niên 2000.","de":"Kurzform aus 밀다 (schieben) + 당기다 (ziehen); verbreitet durch Dating-Shows der 2000er."}'::jsonb,
 '썸 단계에서 흔히 쓰고, 과하면 ''어장관리''로 욕먹는다.',
 '{"en":"Common in the talking stage; overdo it and you get accused of 어장관리 (stringing people along).","ja":"「썸」の段階でよく使い、やりすぎると「어장관리」と非難される。","es":"Común en la fase de tanteo; si te pasas te acusan de 어장관리 (dar falsas esperanzas).","vi":"Hay dùng ở giai đoạn tìm hiểu; quá đà sẽ bị mắng là 어장관리 (thả thính giữ chài).","de":"Üblich in der Kennenlernphase; übertreibt man es, gilt es als 어장관리 (Hinhalten)."}'::jsonb,
 array['삼귀다','어장관리','그린라이트'], 0, 0,
 '[{"lang":"🇺🇸 EN","text":"Push-and-pull dating game"},{"lang":"🇯🇵 JA","text":"恋の駆け引き"},{"lang":"🇨🇳 ZH","text":"恋爱推拉战术"},{"lang":"🇻🇳 VI","text":"Chiêu kéo-đẩy khi yêu"},{"lang":"🇪🇸 ES","text":"Tira y afloja amoroso"},{"lang":"🇩🇪 DE","text":"Hin und Her beim Flirten"}]'::jsonb, null),
('291', '모솔', 'Mo-Sol', 'love', '''모태솔로'' — 연애 경험이 한 번도 없는 사람',
 '{"en":"Single since birth — never once dated","ja":"母胎ソロ — 生まれてから恋愛経験ゼロ","es":"Soltero de nacimiento, sin haber salido nunca","vi":"Ế bẩm sinh — chưa từng yêu ai","de":"Single seit Geburt — noch nie in einer Beziehung"}'::jsonb,
 '[모솔]',
 '[{"type":"명사","definition":"''모태솔로''의 줄임말. 어머니 뱃속(모태)에서부터 솔로였다는 과장으로, 태어나서 한 번도 연애를 못 해 본 사람을 가리킨다.","definition_i18n":{"en":"Short for 모태솔로 (womb single): the exaggeration that someone has been single since the womb — never dated once in their life.","ja":"「母胎ソロ」の略。母のお腹の中からソロだったという誇張で、生まれて一度も恋愛したことがない人を指す。","es":"Abreviatura de 모태솔로 (soltero desde el útero): la exageración de que alguien lleva soltero desde el vientre — jamás ha tenido pareja.","vi":"Viết tắt của 모태솔로 (ế từ trong bụng mẹ): cách nói quá rằng ai đó độc thân từ lúc chưa sinh ra — cả đời chưa yêu lần nào.","de":"Kurz für 모태솔로 (Single ab Mutterleib): die Übertreibung, jemand sei seit dem Mutterleib Single — noch nie in einer Beziehung gewesen."},"examples":[{"kor":"나 모솔이라 소개팅이 너무 떨려.","eng":"I have never dated anyone, so this blind date is terrifying.","ja":"母胎ソロだから合コンが緊張しすぎる。","es":"Nunca he salido con nadie, así que la cita a ciegas me aterra.","vi":"Mình ế bẩm sinh nên đi xem mắt run muốn xỉu.","de":"Ich war noch nie in einer Beziehung, deshalb macht mich das Blind Date fertig."}]}]'::jsonb,
 '''모태''(어머니 뱃속)+''솔로''의 합성 ''모태솔로''를 두 글자로 줄인 말. 2000년대 후반부터 쓰였다.',
 '{"en":"A clipping of 모태 (womb) + 솔로 (solo); the full 모태솔로 dates to the late 2000s.","ja":"「母胎」+「ソロ」の合成語「모태솔로」を2文字に縮めた語。2000年代後半から使われる。","es":"Recorte de 모태 (útero) + 솔로 (solo); la forma completa 모태솔로 data de finales de los 2000.","vi":"Rút gọn của 모태 (bụng mẹ) + 솔로 (độc thân); dạng đầy đủ 모태솔로 có từ cuối thập niên 2000.","de":"Kurzform von 모태 (Mutterleib) + 솔로 (Solo); die Langform 모태솔로 stammt aus den späten 2000ern."}'::jsonb,
 '주로 자기소개나 자조 개그로 쓴다. 남을 놀릴 때 쓰면 무례할 수 있다.',
 '{"en":"Mostly self-deprecating; teasing someone else with it can be rude.","ja":"主に自虐ネタで使う。他人をからかうと失礼になり得る。","es":"Sobre todo autocrítico; usarlo para burlarse de otro puede ser grosero.","vi":"Chủ yếu tự trào; đem trêu người khác có thể bất lịch sự.","de":"Meist selbstironisch; andere damit aufzuziehen kann unhöflich sein."}'::jsonb,
 array['못해솔로','금사빠'], 0, 0,
 '[{"lang":"🇺🇸 EN","text":"Never-dated single"},{"lang":"🇯🇵 JA","text":"母胎ソロ"},{"lang":"🇨🇳 ZH","text":"母胎单身"},{"lang":"🇻🇳 VI","text":"Ế bẩm sinh"},{"lang":"🇪🇸 ES","text":"Soltero de nacimiento"},{"lang":"🇩🇪 DE","text":"Single seit Geburt"}]'::jsonb, array['모태솔로']),
('292', '어장관리', 'Eo-Jang-Gwal-Li', 'love', '여러 이성에게 여지를 주며 붙잡아 두는 것',
 '{"en":"Keeping several admirers on the hook","ja":"複数の相手に気を持たせてキープすること","es":"Tener a varios pretendientes en el anzuelo","vi":"Thả thính giữ chài nhiều người cùng lúc","de":"Mehrere Verehrer gleichzeitig hinhalten"}'::jsonb,
 '[어장관리]',
 '[{"type":"명사","definition":"자기 ''어장''(양식장) 속 물고기를 기르듯, 사귈 마음도 없으면서 여러 이성에게 희망을 주며 관심을 붙잡아 두는 행동.","definition_i18n":{"en":"Managing your fish farm: keeping several admirers hopeful and hooked without any intention of actually dating them.","ja":"自分の養殖場の魚を育てるように、付き合う気もないのに複数の相手に希望を持たせてキープする行動。","es":"Gestionar tu piscifactoría: mantener a varios pretendientes ilusionados sin intención real de salir con ellos.","vi":"Quản lý ao cá của mình: giữ nhiều người theo đuổi luôn hy vọng dù chẳng định yêu ai.","de":"Die eigene Fischzucht pflegen: mehrere Verehrer bei Laune halten, ohne je mit ihnen zusammenkommen zu wollen."},"examples":[{"kor":"답장은 꼬박꼬박 하는데 만나 주진 않아 — 완전 어장관리야.","eng":"She replies to every text but never meets up — textbook fish-farming.","ja":"返信はちゃんとするのに会ってはくれない — 完全にキープされてる。","es":"Contesta todos los mensajes pero nunca queda — puro manejo de pecera.","vi":"Tin nhắn nào cũng trả lời mà hẹn thì né — đúng kiểu nuôi cá trong ao.","de":"Sie antwortet auf jede Nachricht, trifft sich aber nie — klassisches Hinhalten."}]}]'::jsonb,
 '물고기를 가둬 기르는 ''어장''(양식장)에 빗댄 은유. 2000년대 연애 커뮤니티에서 굳어졌다.',
 '{"en":"A metaphor from 어장 (fish farm) — admirers as fish you keep penned; settled in 2000s dating communities.","ja":"魚を囲って育てる「漁場(養殖場)」に例えた比喩。2000年代の恋愛コミュニティで定着。","es":"Metáfora de 어장 (piscifactoría): los pretendientes como peces encerrados; se asentó en los foros de los 2000.","vi":"Ẩn dụ từ 어장 (ao nuôi cá) — người theo đuổi như cá nuôi trong ao; phổ biến từ các diễn đàn thập niên 2000.","de":"Metapher vom 어장 (Fischzucht) — Verehrer als gehaltene Fische; geprägt in den Dating-Foren der 2000er."}'::jsonb,
 '비난조로 쓰는 부정적 표현. 당하는 쪽은 ''어장 속 물고기''라고 한다.',
 '{"en":"Negative and accusatory; the one strung along is called a fish in the farm.","ja":"非難調のネガティブな表現。される側は「漁場の中の魚」と言う。","es":"Negativo y acusatorio; al ilusionado se le llama pez de la pecera.","vi":"Mang nghĩa chê trách; người bị giữ gọi là cá trong ao.","de":"Negativ und vorwurfsvoll; der Hingehaltene ist der Fisch im Teich."}'::jsonb,
 array['밀당','그린라이트'], 0, 0,
 '[{"lang":"🇺🇸 EN","text":"Stringing admirers along"},{"lang":"🇯🇵 JA","text":"キープ・思わせぶり"},{"lang":"🇨🇳 ZH","text":"养鱼(吊着暧昧对象)"},{"lang":"🇻🇳 VI","text":"Thả thính nuôi cá"},{"lang":"🇪🇸 ES","text":"Tener en el anzuelo"},{"lang":"🇩🇪 DE","text":"Verehrer hinhalten"}]'::jsonb, null),
('293', '환승이별', 'Hwan-Seung-I-Byeol', 'love', '새 사람을 만들어 두고 갈아타듯 하는 이별',
 '{"en":"Transfer breakup — lining up the next one before leaving","ja":"乗り換え別れ — 次を用意してから別れること","es":"Ruptura con transbordo: dejar a alguien con el siguiente ya listo","vi":"Chia tay kiểu chuyển tuyến — có người mới rồi mới bỏ","de":"Umsteige-Trennung — erst der Neue, dann das Ende"}'::jsonb,
 '[환승이별]',
 '[{"type":"명사","definition":"버스·지하철을 갈아타듯, 새 연애 상대를 미리 만들어 두고 기존 연인과 헤어지는 이별. 이별과 동시에 새 연애가 시작된다.","definition_i18n":{"en":"Breaking up the way you transfer buses: the next partner is already lined up, so the new romance starts the moment the old one ends.","ja":"バスや地下鉄を乗り換えるように、新しい相手を用意してから今の恋人と別れること。別れと同時に新しい恋愛が始まる。","es":"Romper como quien hace transbordo: el siguiente ya está listo y la nueva relación empieza en cuanto acaba la anterior.","vi":"Chia tay như chuyển tuyến xe: đã chuẩn bị sẵn người mới, vừa dứt mối cũ là bắt đầu mối mới.","de":"Sich trennen wie beim Umsteigen: Der Nächste steht schon bereit, die neue Beziehung beginnt mit dem Ende der alten."},"examples":[{"kor":"걔 헤어지자마자 새 남친 생겼대 — 환승이별이지.","eng":"She had a new boyfriend the day they broke up — a transfer breakup.","ja":"別れた途端に新しい彼氏ができたって — 乗り換え別れでしょ。","es":"Tuvo novio nuevo el mismo día de romper — ruptura con transbordo.","vi":"Vừa chia tay đã có bạn trai mới — đúng kiểu chia tay chuyển tuyến.","de":"Am Tag der Trennung hatte sie schon einen Neuen — klassische Umsteige-Trennung."}]}]'::jsonb,
 '대중교통 ''환승''(갈아타기)에 빗댄 은유. 2021년 연애 예능 ''환승연애''로 단어가 대중화됐다.',
 '{"en":"A metaphor from transit transfers (환승); mainstreamed by the 2021 dating show 환승연애 (Transit Love).","ja":"公共交通の「乗り換え」に例えた比喩。2021年の恋愛番組『換乗恋愛』で大衆化した。","es":"Metáfora del transbordo (환승) de transporte; popularizada por el programa de citas 환승연애 (2021).","vi":"Ẩn dụ từ 환승 (chuyển tuyến) giao thông; phổ biến nhờ show hẹn hò 환승연애 (2021).","de":"Metapher vom Umsteigen (환승) im Nahverkehr; bekannt durch die Dating-Show 환승연애 (2021)."}'::jsonb,
 '이별당한 쪽이 배신감을 담아 비난조로 쓴다.',
 '{"en":"Said accusingly, usually by the one who got left behind.","ja":"別れられた側が裏切られた気持ちを込めて非難調で使う。","es":"Lo dice con reproche quien fue dejado.","vi":"Người bị bỏ thường nói với giọng trách móc.","de":"Meist vorwurfsvoll von der verlassenen Seite gesagt."}'::jsonb,
 array['어장관리','금사빠'], 0, 0,
 '[{"lang":"🇺🇸 EN","text":"Transfer breakup"},{"lang":"🇯🇵 JA","text":"乗り換え別れ"},{"lang":"🇨🇳 ZH","text":"无缝衔接分手"},{"lang":"🇻🇳 VI","text":"Chia tay chuyển tuyến"},{"lang":"🇪🇸 ES","text":"Ruptura con transbordo"},{"lang":"🇩🇪 DE","text":"Umsteige-Trennung"}]'::jsonb, null),
('294', '그린라이트', 'Geu-Rin-La-I-Teu', 'love', '상대도 나에게 마음이 있다는 청신호',
 '{"en":"Green light — a sign the feeling is mutual","ja":"グリーンライト — 脈ありのサイン","es":"Luz verde: señal de que le gustas","vi":"Đèn xanh — tín hiệu đối phương cũng thích mình","de":"Grünes Licht — Zeichen, dass Interesse besteht"}'::jsonb,
 '[그린라이트]',
 '[{"type":"명사","definition":"교통 신호의 초록불처럼, 상대도 나에게 호감이 있으니 다가가도 된다는 신호. ''이거 그린라이트야?''처럼 상대 행동의 의미를 물을 때 쓴다.","definition_i18n":{"en":"Like a traffic light turning green: a sign the other person likes you back, so it is safe to make a move. Often asked as is this a green light?","ja":"信号の青のように、相手も好意があるから近づいていいというサイン。「これって脈あり?」のように相手の行動の意味を尋ねるときに使う。","es":"Como un semáforo en verde: señal de que también le gustas y puedes avanzar. Se pregunta mucho ¿esto es luz verde?","vi":"Như đèn giao thông chuyển xanh: dấu hiệu đối phương cũng thích bạn, cứ tiến tới. Hay hỏi kiểu đây có phải đèn xanh không?","de":"Wie eine Ampel auf Grün: das Zeichen, dass die Gefühle erwidert werden und man vorangehen darf. Oft gefragt: Ist das grünes Licht?"},"examples":[{"kor":"먼저 연락 오는 거면 그린라이트 아니야?","eng":"If she texts first, is that not a green light?","ja":"向こうから連絡くるなら脈ありじゃない?","es":"Si te escribe primero, ¿no es luz verde?","vi":"Người ta nhắn trước thì là đèn xanh còn gì?","de":"Wenn sie zuerst schreibt, ist das nicht grünes Licht?"}]}]'::jsonb,
 '영어 green light(청신호)에서 온 외래어. 2013년 JTBC ''마녀사냥''의 ''그린라이트를 켜 줘'' 코너로 연애 용어로 굳어졌다.',
 '{"en":"From the English green light; fixed as a dating term by the turn on the green light segment of JTBC show 마녀사냥 (2013).","ja":"英語のgreen lightから。2013年JTBC『魔女狩り』の「グリーンライトを点けて」コーナーで恋愛用語として定着。","es":"Del inglés green light; se fijó como término amoroso con la sección enciende la luz verde del programa 마녀사냥 (JTBC, 2013).","vi":"Từ tiếng Anh green light; thành thuật ngữ hẹn hò nhờ chuyên mục bật đèn xanh của show 마녀사냥 (JTBC, 2013).","de":"Vom englischen green light; als Dating-Begriff etabliert durch die Rubrik ‚Mach das grüne Licht an‘ der JTBC-Show 마녀사냥 (2013)."}'::jsonb,
 '상대 행동이 호감 신호인지 friends에게 판정을 구할 때 흔히 쓴다. 반대는 ''레드라이트''.',
 '{"en":"Used when asking friends to judge whether a behaviour signals interest; the opposite is 레드라이트 (red light).","ja":"相手の行動が脈ありか友達に判定を求めるときによく使う。反対は「レッドライト」。","es":"Se usa al pedir a los amigos que juzguen si un gesto es señal de interés; lo contrario es 레드라이트.","vi":"Dùng khi nhờ bạn bè phán xem hành động của đối phương có phải tín hiệu thích mình; ngược lại là 레드라이트.","de":"Gebraucht, wenn Freunde beurteilen sollen, ob ein Verhalten Interesse signalisiert; das Gegenteil ist 레드라이트."}'::jsonb,
 array['심쿵','삼귀다','밀당'], 0, 0,
 '[{"lang":"🇺🇸 EN","text":"Green light (mutual interest)"},{"lang":"🇯🇵 JA","text":"脈ありサイン"},{"lang":"🇨🇳 ZH","text":"绿灯(有戏的信号)"},{"lang":"🇻🇳 VI","text":"Đèn xanh tình cảm"},{"lang":"🇪🇸 ES","text":"Luz verde (interés mutuo)"},{"lang":"🇩🇪 DE","text":"Grünes Licht (Interesse)"}]'::jsonb, null);

